class BoundedQueue<T>(private val cap: Int) {
    private val q = ArrayDeque<T>()

    @Synchronized fun put(item: T) {
        val mon = this as java.lang.Object
        while (q.size == cap) mon.wait()      // predicate loop
        q.addLast(item)
        mon.notifyAll()
    }
}

