private val mutex = Mutex()
private val changed = Channel<Unit>(Channel.CONFLATED)
suspend fun put(item: T) {
    while (true) {
        mutex.withLock { if (q.size < cap) { q.addLast(item); changed.trySend(Unit); return } }
        changed.receive()               // wait without holding the mutex
    }
}
